import{_ as a,o,c as e,ag as l}from"./chunks/framework.D5hoimZQ.js";const k=JSON.parse('{"title":"科学日报 · 2026-09-14（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-14.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-14.md"}'),t={name:"topics/ai-system-architecture/science-daily-2026-09-14.md"};function r(s,i,n,c,d,u){return o(),e("div",null,[...i[0]||(i[0]=[l('<h1 id="科学日报-·-2026-09-14-ai-系统架构" tabindex="-1">科学日报 · 2026-09-14（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-09-14-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-09-14（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> — 第25期</p></blockquote><hr><h2 id="生物在环-自适应命中发现的-assayloop-arxiv" tabindex="-1">生物在环：自适应命中发现的 AssayLoop（arXiv） <a class="header-anchor" href="#生物在环-自适应命中发现的-assayloop-arxiv" aria-label="Permalink to &quot;生物在环：自适应命中发现的 AssayLoop（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ arXiv: 2609.11877</p></blockquote><ul><li>问题：有限预算下顺序选择生物学实验（CRISPR 筛选为典型），现有基准规模不足、难以跨实验学习采集策略。</li><li>AssayBench-Loop：1,389 个跨五类表型的 CRISPR 筛选基准，覆盖此前缺口。</li><li>AssayLoop = AssayFormer（跨历史筛选训练的 transformer <strong>平摊采集策略</strong>，从实验反馈自适应）+ LLM 生物学先验（自适应移交）；AssayLLM 展示可经任务后训练直改 LLM。</li><li>结果：时间留出筛选上富集 5.67×、检测约 5% 候选库恢复 27.7% 命中，优于现有自适应方法；随历史训练数据增加而提升。</li><li>洞察：<strong>把完成实验当训练数据、学下一步测什么</strong>——&quot;实验即为数据&quot;的平摊主动学习范式，AI + 湿实验闭环。</li></ul><h2 id="逐-token-门控统一族-在线蒸馏-fkl-rkl-混合-arxiv" tabindex="-1">逐 token 门控统一族：在线蒸馏 FKL/RKL 混合（arXiv） <a class="header-anchor" href="#逐-token-门控统一族-在线蒸馏-fkl-rkl-混合-arxiv" aria-label="Permalink to &quot;逐 token 门控统一族：在线蒸馏 FKL/RKL 混合（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ arXiv: 2609.11768</p></blockquote><ul><li>逐 token 门控前向/反向 KL 已成在线知识蒸馏（OPD）标准，但 EOPD/ToDi 等各固定单一门控信号与方向，从未直接对比。</li><li>提出四系数参数化 λ_t = σ(a·h_t + b·u(x) + c + d·gap_t)，EOPD/ToDi 是其 1D 限制，新增多通道 + 显式偏置。</li><li>Qwen3-32B→4B 在 TweetEval：全族在 36/33 单元胜匹配幅度的单通道一维限制；隔离实验把动态门控置于有效-KL 匹配静态基线前。</li><li>洞察：价值首先是<strong>共享坐标系</strong>——统一描述逐 token 门控设计、支持诚实的跨方法比较（作者明确区分方向性证据与独立假设检验）。</li></ul><h2 id="locus-任务感知低秩后训练-省-token-语言生成-arxiv" tabindex="-1">LOCUS：任务感知低秩后训练，省 token 语言生成（arXiv） <a class="header-anchor" href="#locus-任务感知低秩后训练-省-token-语言生成-arxiv" aria-label="Permalink to &quot;LOCUS：任务感知低秩后训练，省 token 语言生成（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ arXiv: 2609.11739</p></blockquote><ul><li>服务成本随输出长度直接缩放，标准偏好对齐常在无效用增益下助长冗长。</li><li>LOCUS：选择<strong>任务感知低秩适配子空间</strong>，在效用约束下最小化输出 token 成本；子空间内保留原生偏好目标 + 冻结骨干。</li><li>HH-RLHF（Pythia-2.8B / Qwen2.5-3B，对比全参数 DPO/DrDPO/SamPO）：续写长度 Pythia 最多 −39.84%、Qwen −14.87~−17.58%，仅更新 0.24–0.28% 参数，偏好诊断无实质变化。</li><li>洞察：把&quot;对齐方向&quot;与&quot;长度经济性&quot;解耦——低成本低秩后训练即可赢得 token 经济性，对推理成本有直接意义。</li></ul><h2 id="智能体分歧时-贝叶斯反向推理作无标签锚点-arxiv" tabindex="-1">智能体分歧时：贝叶斯反向推理作无标签锚点（arXiv） <a class="header-anchor" href="#智能体分歧时-贝叶斯反向推理作无标签锚点-arxiv" aria-label="Permalink to &quot;智能体分歧时：贝叶斯反向推理作无标签锚点（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ arXiv: 2609.11709</p></blockquote><ul><li>现有集体决策（投票/选举规则/LLM 裁判）都依赖<strong>前向推理</strong>（证据→标签单向），聚合估计共享同一分解而可能<strong>继承相关误差</strong>。</li><li>反向思路：经显式似然做<strong>贝叶斯反向推理</strong>构建反向后验；前向/反向提供不同分解的近似，用<strong>Jensen–Shannon 散度</strong>按跨路径一致性排序 → MinJS（硬选）、FwdJS（软加权）、LogLin（对数线性融合）。</li><li>DDXPlus 五个 LLM 骨干：MinJS 全面优于随机，LogLin 最优且在最分歧子集上增益最大。反向后验自身准确率弱，却是<strong>有用的互补锚点</strong>。</li><li>洞察：不同&quot;分解方式&quot;共享误差更少——用跨路径一致性替代标签先验，是少标签/无标签多智能体聚合的可行路线。</li></ul><h2 id="cobra-skills-上下文赌博机引导的技能进化-arxiv" tabindex="-1">COBRA-Skills：上下文赌博机引导的技能进化（arXiv） <a class="header-anchor" href="#cobra-skills-上下文赌博机引导的技能进化-arxiv" aria-label="Permalink to &quot;COBRA-Skills：上下文赌博机引导的技能进化（arXiv）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-14.md</code> ｜ arXiv: 2609.11682</p></blockquote><ul><li>现有技能优化常靠昂贵的执行评估与大量任务数据。</li><li>COBRA-Skills：把技能优化形式化为对动态演化候选空间的<strong>预算受限顺序优化</strong>，耦合上下文赌博机引导的优先级选择 + 证据锚定的技能进化，选择性评估有前景候选。</li><li>六个异构智能体基准 × 三个目标模型：最强平均性能，相对 SkillOpt 降成本 55–58%，每基准仅 50 个独特优化示例；对 harness 变化稳健，目标模型自用于生成/精炼仍有效。</li><li>洞察：&quot;预算内高效进化技能&quot;——控制评估成本、用证据锚定进化方向，是智能体技能持续升级的轻量配方。</li></ul>',18)])])}const p=a(t,[["render",r]]);export{k as __pageData,p as default};
